// Edita o borra un gasto ya guardado de una salida con Ema (el lápiz de la app)
const TOKEN = 'mercado-7d41c2a9e05b';
let b = $input.first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const falla = (error) => [{ json: { ok: false, error } }];
if (b.token !== TOKEN) return falla('token');
const id = String(b.id || '').trim();
if (!/^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i.test(id)) return falla('id');
const accion = b.accion === 'borrar' ? 'borrar' : b.accion === 'editar' ? 'editar' : '';
if (!accion) return falla('accion');
if (accion === 'borrar') return [{ json: { ok: true, id, accion } }];
const concepto = String(b.concepto || '').replace(/[<>{}\[\]]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80);
if (!concepto) return falla('concepto');
const monto = Math.round(Number(b.monto));
if (!(monto > 0) || monto > 100000000) return falla('monto');
// «medio»: digital (sale de la cuenta) o efectivo (Monto 0 y el valor en «Efectivo», igual que movimiento-nuevo)
const medio = String(b.medio || '').toLowerCase() === 'efectivo' ? 'efectivo' : 'digital';
const categoria = ['Salidas', 'Salidas Ema'].includes(b.categoria) ? b.categoria : '';
return [{ json: { ok: true, id, accion, concepto, monto, medio, categoria } }];

// Con la página actual de Notion arma el cambio. Solo toca gastos de salidas con Ema (así un id equivocado no cambia otra cosa)
const v = $('Validar cambio').first().json;
const pg = $input.first().json || {};
const falla = (error) => [{ json: { ok: false, error } }];
// Notion no la encuentra (borrada o id malo) → 400; Notion caída o sin permiso de momento → 502 y la cola de la app reintenta
if (pg.object !== 'page' || !pg.properties) return falla(/404|object_not_found|400|validation/i.test(JSON.stringify(pg.error || '')) || !pg.error ? 'no-existe' : 'notion');
const pr = pg.properties;
const sel = (n) => pr[n] && pr[n].select ? pr[n].select.name : null;
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const esEma = sel('Salida') === 'Con Ema' || sel('Categoría') === 'Salidas Ema';
if (sel('Tipo') !== 'Gasto' || !esEma) return falla('no-es-salida');
const enPapelera = !!(pg.archived || pg.in_trash);
// borrar = a la papelera de Notion (de ahí se puede recuperar)
if (v.accion === 'borrar') return [{ json: { ok: true, id: v.id, accion: 'borrar', yaEstaba: enPapelera, cuerpo: { archived: true } } }];
if (enPapelera) return falla('no-existe');
const ef = v.medio === 'efectivo';
// regla del efectivo: Monto 0 (no toca la cuenta) y el valor en «Efectivo». Digital: el valor en Monto y «Efectivo» vacío
const props = { Concepto: { title: [{ text: { content: v.concepto } }] }, Monto: { number: ef ? 0 : v.monto } };
const hayCol = !!pr.Efectivo;   // Notion devuelve todas las columnas de la base: si «Efectivo» no viene, esa columna no existe
if (hayCol) props.Efectivo = { number: ef ? v.monto : null };
// cambió en qué fue: comer afuera = Salidas; entradas, juegos, parqueadero = Salidas Ema (como lo guarda la app)
const cat = sel('Categoría');
if (v.categoria && cat !== v.categoria && ['Salidas', 'Salidas Ema'].includes(cat)) {
  props['Categoría'] = { select: { name: v.categoria } };
  if (pr.Salida && sel('Salida') !== 'Con Ema') props.Salida = { select: { name: 'Con Ema' } };   // sigue siendo de la salida aunque deje de ser «Salidas Ema»
}
// la nota de efectivo que pone movimiento-nuevo se pone o se quita según el medio
// con la columna: «Pagado en efectivo: no sale de la cuenta»; sin ella (respaldo): «Pagado en efectivo $4.500: …» y el valor se lee de la nota
const NOTA_RE = /^Pagado en efectivo(?: \$[\d.]+)?: no sale de la cuenta/;
const NOTA = hayCol ? 'Pagado en efectivo: no sale de la cuenta' : 'Pagado en efectivo $' + String(v.monto).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ': no sale de la cuenta';
const antes = txt(pr.Notas && pr.Notas.rich_text);
const m0 = antes.match(NOTA_RE);
const resto = m0 ? antes.slice(m0[0].length).replace(/^\s*·\s*/, '').trim() : antes;
const nueva = (ef ? NOTA + (resto ? ' · ' + resto : '') : resto).slice(0, 300);
if (pr.Notas && nueva !== antes) props.Notas = { rich_text: nueva ? [{ text: { content: nueva } }] : [] };
return [{ json: { ok: true, id: v.id, accion: 'editar', medio: v.medio, aviso: ef && !hayCol ? 'efectivo-sin-columna' : null, cuerpo: { properties: props } } }];

// ¿Notion lo guardó? (si Notion falla, la app recibe 502 y la cola lo reintenta después)
const r = $input.first().json || {};
const a = $('Armar cambio').first().json;
if (r.object !== 'page') {
  // Notion rechazó la propiedad (por ejemplo, «Efectivo» no existe): se dice cuál; otra falla = 502 y la cola reintenta
  const t = JSON.stringify(r);
  const m = t.match(/([^"\\.,:{}\[\]]{1,60}?) is not a property that exists/i);
  return [{ json: m ? { ok: false, error: 'sin-columna', columna: m[1].trim() } : { ok: false, error: 'notion' } }];
}
return [{ json: { ok: true, id: a.id, accion: a.accion, medio: a.medio || null, aviso: a.aviso || null } }];
